def can_open_all(keys):
    seen = {0}
    stack = [0]
    while stack:
        room = stack.pop()
        for k in keys[room]:
            if k not in seen:
                seen.add(k)
                stack.append(k)
    return len(seen) == len(keys)

assert can_open_all([[1, 3], [3, 0, 1], [2], [0]]) is False
assert can_open_all([[1], [2], [3], []]) is True
print(can_open_all([[1, 3], [3, 0, 1], [2], [0]]))
